#!/usr/bin/env python3
"""news-image-20261117: write the 17 November 2026 world-news front page.

The image is embedded below as one base64 line: a JPEG of the front page
(the file it writes is still named entry.png, as the rules require).
Standard library only, no network, deterministic: every run writes the
same bytes, so the two grading runs agree byte for byte.

The front page names the day in its masthead and pictures six stories
that defined Tuesday 17 November 2026: the U.S. strike on Iran's Qeshm
Island, Ukraine's strike dropping a span of the Kerch Bridge, Nvidia's
record $115 billion quarter, Trump's trip to Shenzhen for APEC talks
with Xi and Putin, the Ebola surge in DR Congo, and Nepal becoming the
first country with UN loss-and-damage funds set aside after floods.
"""
import base64
import os

DATA = ""

def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(base64.b64decode(DATA))

if __name__ == "__main__":
    main()
